import{_ as t,c as a,o as r,ae as n}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Exchange Rates","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/exchange-rates/index.md","filePath":"api/graphql-api/admin/settings/exchange-rates/index.md"}'),d={name:"api/graphql-api/admin/settings/exchange-rates/index.md"};function o(i,e,s,c,h,g){return r(),a("div",null,e[0]||(e[0]=[n('<h1 id="exchange-rates" tabindex="-1">Exchange Rates <a class="header-anchor" href="#exchange-rates" aria-label="Permalink to &quot;Exchange Rates&quot;">​</a></h1><p>The Exchange Rates menu defines the conversion rate from your store&#39;s <strong>base currency</strong> to each other currency you allow. When a shopper views the storefront in a non-base currency, prices are converted using the rate stored here. It mirrors the admin <strong>Settings → Exchange Rates</strong> screen.</p><h2 id="what-an-exchange-rate-row-holds" tabindex="-1">What an exchange rate row holds <a class="header-anchor" href="#what-an-exchange-rate-row-holds" aria-label="Permalink to &quot;What an exchange rate row holds&quot;">​</a></h2><p>Each row links one <strong>target currency</strong> to a single numeric <strong>rate</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td>Numeric id of the exchange-rate row.</td></tr><tr><td><code>id</code></td><td>Resource IRI (e.g. <code>/api/admin/settings/exchange-rates/11</code>).</td></tr><tr><td><code>targetCurrency</code></td><td>Numeric id of the currency this rate converts <strong>to</strong>.</td></tr><tr><td><code>targetCurrencyCode</code></td><td>The target currency&#39;s 3-letter code (e.g. <code>EUR</code>), resolved inline for convenience.</td></tr><tr><td><code>targetCurrencyName</code></td><td>The target currency&#39;s display name (e.g. <code>Euro</code>), resolved inline.</td></tr><tr><td><code>rate</code></td><td>The multiplier applied to a base-currency price to express it in the target currency.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>The base currency itself has no exchange-rate row — a base-to-base rate would always be <code>1</code>.</p><h2 id="one-rate-per-target-currency" tabindex="-1">One rate per target currency <a class="header-anchor" href="#one-rate-per-target-currency" aria-label="Permalink to &quot;One rate per target currency&quot;">​</a></h2><p>Each target currency may have <strong>at most one</strong> exchange rate. Trying to create a second rate for a currency that already has one is rejected. To change an existing currency&#39;s rate, update the existing row rather than creating a new one.</p><h2 id="auto-sync-—-the-update-rates-action" tabindex="-1">Auto-sync — the &quot;Update Rates&quot; action <a class="header-anchor" href="#auto-sync-—-the-update-rates-action" aria-label="Permalink to &quot;Auto-sync — the &quot;Update Rates&quot; action&quot;">​</a></h2><p>Instead of typing every rate by hand, the <strong>Update Rates</strong> action fetches live rates for all target currencies in one call from your store&#39;s <strong>configured external rate provider</strong> (set under the store&#39;s currency/API configuration). This is the <code>createAdminSettingsExchangeRateUpdateRates</code> mutation. It takes an empty input and refreshes every existing target currency&#39;s rate. Because it reaches out to an external service, it can fail when no provider is configured or the provider&#39;s credentials/network are unavailable — in that case the response carries an <code>errors</code> entry with the provider&#39;s message and no rates change.</p><h2 id="creating-updating-deleting" tabindex="-1">Creating, updating, deleting <a class="header-anchor" href="#creating-updating-deleting" aria-label="Permalink to &quot;Creating, updating, deleting&quot;">​</a></h2><ul><li><strong>Create</strong> a rate by supplying a <code>targetCurrency</code> id and a <code>rate</code>.</li><li><strong>Update</strong> a rate to change its <code>rate</code> (the target currency stays fixed).</li><li><strong>Delete</strong> a single rate, or <strong>mass-delete</strong> several at once by their numeric ids.</li></ul><p>Deleting a rate does not delete the currency — only the conversion entry. A target currency with no rate simply isn&#39;t offered for conversion until a rate is added (or the auto-sync supplies one).</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/list.html">List exchange rates</a></td><td><code>adminSettingsExchangeRates</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/detail.html">Get a single exchange rate</a></td><td><code>adminSettingsExchangeRate(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/create.html">Create an exchange rate</a></td><td><code>createAdminSettingsExchangeRate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/update.html">Update an exchange rate</a></td><td><code>updateAdminSettingsExchangeRate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/delete.html">Delete an exchange rate</a></td><td><code>deleteAdminSettingsExchangeRate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/mass-delete.html">Mass delete exchange rates</a></td><td><code>createAdminSettingsExchangeRateMassDelete</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/update-rates.html">Update rates (auto-sync)</a></td><td><code>createAdminSettingsExchangeRateUpdateRates</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.exchange_rates.create</code> / <code>.edit</code> / <code>.delete</code> (<code>update-rates</code> uses <code>.edit</code>).</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const u=t(d,[["render",o]]);export{p as __pageData,u as default};
